messages.content:
{
  "type": "object",
  "properties": {
    "type": {
      "const": "input_audio"
    },
    "input_audio": {
      "type": "object",
      "properties": {
        "data": {
          "type": "string",
          "description": "Base64 encoded audio data."
        },
        "format": {
          "enum": [
            "wav",
            "mp3"
          ],
          "description": "The format of the encoded audio data."
        }
      },
      "required": [
        "data",
        "format"
      ],
      "description": "The audio data and its format."
    }
  },
  "required": [
    "type",
    "input_audio"
  ],
  "description": "An audio rich content part."
}

{
  "type": "object",
  "properties": {
    "type": {
      "enum": [
        "video_url",
        "input_video"
      ]
    },
    "video_url": {
      "type": "object",
      "properties": {
        "url": {
          "type": "string",
          "description": "URL of the video."
        }
      },
      "required": [
        "url"
      ]
    }
  },
  "required": [
    "type",
    "video_url"
  ],
  "description": "A video rich content part."
}

{
  "type": "object",
  "properties": {
    "type": {
      "const": "image_url"
    },
    "image_url": {
      "type": "object",
      "properties": {
        "url": {
          "type": "string",
          "description": "Either a URL of the image or the base64 encoded image data."
        },
        "detail": {
          "anyOf": [
            {
              "enum": [
                "auto",
                "low",
                "high"
              ],
              "description": "Specifies the detail level of the image."
            },
            {
              "type": "null"
            }
          ]
        }
      },
      "required": [
        "url"
      ],
      "description": "The URL of the image and its optional detail level."
    }
  },
  "required": [
    "type",
    "image_url"
  ],
  "description": "An image rich content part."
}

{
  "type": "object",
  "properties": {
    "type": {
      "const": "image_url"
    },
    "image_url": {
      "type": "object",
      "properties": {
        "url": {
          "type": "string",
          "description": "Either a URL of the image or the base64 encoded image data."
        },
        "detail": {
          "anyOf": [
            {
              "enum": [
                "auto",
                "low",
                "high"
              ],
              "description": "Specifies the detail level of the image."
            },
            {
              "type": "null"
            }
          ]
        }
      },
      "required": [
        "url"
      ],
      "description": "The URL of the image and its optional detail level."
    }
  },
  "required": [
    "type",
    "image_url"
  ],
  "description": "An image rich content part."
}
